/* Research OS v2 document design: Whiteboard (light) and Chalkboard (dark).
   Components inherit these offline tokens; avoid per-session overrides. */
:root {
  color-scheme: light dark;
  /* Whiteboard: warm low-glare board, marker-dark ink. Every text pair meets WCAG AA. */
  --ros-bg: #eeece4;
  --ros-surface: #fbfaf6;
  --ros-surface-subtle: #f3f1ea;
  --ros-surface-strong: #e8e5db;
  --ros-text: #1e2a2b;
  --ros-text-muted: #4f5b5a;
  --ros-border: #ddd9ce;
  --ros-border-strong: #8a867a;
  --ros-accent: #1f5f8b;
  --ros-accent-hover: #184e73;
  --ros-accent-press: #133e5c;
  --ros-accent-bg: #e3edf4;
  --ros-info: var(--ros-accent);
  --ros-success: #2e6b4a;
  --ros-success-bg: #e4f0e8;
  --ros-warning: #7a5300;
  --ros-warning-bg: #fbefc8;
  --ros-danger: #a63a2e;
  --ros-danger-bg: #f7e4e0;
  --ros-practice: #5b4a9a;
  --ros-practice-bg: #ece8f6;
  --ros-on-accent: #ffffff;
  /* Focus is amber, never the selection blue, so keyboard position is unmistakable. */
  --ros-focus: #b5650a;
  --ros-radius-sm: 6px;
  --ros-radius-md: 10px;
  --ros-radius-lg: 14px;
  --ros-shadow-sm: 0 1px 2px rgb(30 42 43 / 6%), 0 6px 18px rgb(30 42 43 / 6%);
  --ros-content-width: 840px;
  --ros-wide-width: 1120px;
  /* Installed fonts are used when present; the stacks fall back to the previous system faces. */
  --ros-font-body: "Source Serif 4", Georgia, Cambria, serif;
  --ros-font-ui: "Atkinson Hyperlegible Next", "Atkinson Hyperlegible", "Segoe UI", system-ui, sans-serif;
  --ros-font-mono: "Atkinson Hyperlegible Mono", Consolas, ui-monospace, monospace;
  --ros-control-height: 44px;
  --ros-ease: .12s ease;
  --ros-space-1: 4px;
  --ros-space-2: 8px;
  --ros-space-3: 12px;
  --ros-space-4: 16px;
  --ros-space-5: 24px;
  --ros-space-6: 32px;
  --ros-space-7: 48px;
  --ros-space-8: 64px;
  /* Compatibility aliases for existing locally approved runtime components. */
  --ros-fg: var(--ros-text);
  --ros-muted: var(--ros-text-muted);
  --ros-panel: var(--ros-surface);
  --ros-code-bg: var(--ros-surface-subtle);
  --ros-ui: var(--ros-font-ui);
  font: 18px/1.72 var(--ros-font-body);
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme=light]) {
    /* Chalkboard: green slate rather than black, soft chalk accents. */
    color-scheme: dark;
    --ros-bg: #131a17; --ros-surface: #1e2a25; --ros-surface-subtle: #25332d; --ros-surface-strong: #2e3e37;
    --ros-text: #ecebe4; --ros-text-muted: #b7c0b9;
    --ros-border: #34443d; --ros-border-strong: #71857b;
    --ros-accent: #8cc4e8; --ros-accent-hover: #a6d3f0; --ros-accent-press: #74b2da; --ros-accent-bg: #263c45;
    --ros-success: #9ad5a8; --ros-success-bg: #233a2c;
    --ros-warning: #f2d27a; --ros-warning-bg: #3a3320;
    --ros-danger: #f2a08f; --ros-danger-bg: #3d2724;
    --ros-practice: #c6b8f0; --ros-practice-bg: #2d2a3d;
    --ros-on-accent: #0e1a15; --ros-focus: #f2d27a;
    --ros-shadow-sm: 0 1px 2px rgb(0 0 0 / 30%), 0 8px 24px rgb(0 0 0 / 22%);
  }
}
:root[data-theme=dark] {
  color-scheme: dark;
  --ros-bg: #131a17; --ros-surface: #1e2a25; --ros-surface-subtle: #25332d; --ros-surface-strong: #2e3e37;
  --ros-text: #ecebe4; --ros-text-muted: #b7c0b9;
  --ros-border: #34443d; --ros-border-strong: #71857b;
  --ros-accent: #8cc4e8; --ros-accent-hover: #a6d3f0; --ros-accent-press: #74b2da; --ros-accent-bg: #263c45;
  --ros-success: #9ad5a8; --ros-success-bg: #233a2c;
  --ros-warning: #f2d27a; --ros-warning-bg: #3a3320;
  --ros-danger: #f2a08f; --ros-danger-bg: #3d2724;
  --ros-practice: #c6b8f0; --ros-practice-bg: #2d2a3d;
  --ros-on-accent: #0e1a15; --ros-focus: #f2d27a;
  --ros-shadow-sm: 0 1px 2px rgb(0 0 0 / 30%), 0 8px 24px rgb(0 0 0 / 22%);
}
:root[data-theme=light] { color-scheme: light; }
* { box-sizing: border-box; }
body { background: var(--ros-bg); color: var(--ros-text); margin: 0; }
main {
  max-width: calc(var(--ros-content-width) + 2 * var(--ros-space-7));
  margin: var(--ros-space-6) auto;
  padding: var(--ros-space-7) var(--ros-space-7) var(--ros-space-8);
  min-width: 0; overflow-wrap: anywhere;
}
.ros-document { background: var(--ros-surface); border-radius: var(--ros-radius-lg); box-shadow: var(--ros-shadow-sm); }

/* Header: the title and its context only. */
.ros-session-header, main > header { margin-bottom: var(--ros-space-5); }
.ros-session-header h1 { margin-top: 0; }
h1, h2, h3, h4, h5, h6 { line-height: 1.35; color: var(--ros-text); }
h1 { font: 600 40px/1.15 var(--ros-font-body); letter-spacing: -.02em; margin: var(--ros-space-5) 0 var(--ros-space-3); }
h2 { font: 700 25px/1.3 var(--ros-font-ui); letter-spacing: -.01em; margin: var(--ros-space-7) 0 var(--ros-space-4); }
h3 { font: 700 20px/1.4 var(--ros-font-ui); margin: var(--ros-space-6) 0 var(--ros-space-3); }
h4 { font: 700 18px/1.45 var(--ros-font-ui); margin: var(--ros-space-5) 0 var(--ros-space-3); }
h5, h6 { font: 700 16px/1.5 var(--ros-font-ui); margin: var(--ros-space-5) 0 var(--ros-space-2); }
main > h1 { font-size: 30px; }
.ros-session-context { font-size: 19px; line-height: 1.6; color: var(--ros-text-muted); margin: 0; }
p { margin: var(--ros-space-4) 0; }
strong { font-weight: 700; }
a { color: var(--ros-accent); text-underline-offset: .2em; }
a:hover { color: var(--ros-accent-hover); }
.ros-link-target { color: var(--ros-text-muted); font-size: .85em; overflow-wrap: anywhere; }
