  .ros-toc { float: left; position: sticky; top: 24px; width: 220px; margin: 0 140px 0 -360px; max-height: calc(100vh - 48px); overflow-y: auto; }
  .ros-toc > details { background: transparent; }
  .ros-toc summary { list-style: none; padding: 0 12px; min-height: 32px; font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .09em; color: var(--ros-text-muted); }
  .ros-toc summary::-webkit-details-marker { display: none; }
  .ros-toc ul { padding: 0; }
}
:is(h1,h2,h3,h4,h5,h6)[data-ros] { background: none; border: 0; border-radius: 0; }

/* Callouts separate by tone, not by stacked borders. */
blockquote { margin: var(--ros-space-5) 0; padding: var(--ros-space-1) var(--ros-space-5); border-radius: var(--ros-radius-md); background: var(--ros-surface-subtle); color: var(--ros-text-muted); }
.ros-callout { --ros-callout-accent: var(--ros-info); --ros-callout-bg: var(--ros-accent-bg); border: 0; border-radius: var(--ros-radius-md); margin: var(--ros-space-5) 0; background: var(--ros-callout-bg); overflow: hidden; }
.ros-callout-header { font: 700 15px/1.5 var(--ros-font-ui); padding: var(--ros-space-3) var(--ros-space-5) 0; background: var(--ros-callout-bg); color: var(--ros-callout-accent); }
