:is(section,div,aside)[data-ros=definition], :is(section,div,aside)[data-ros=concept], :is(section,div,aside)[data-ros=evidence], :is(section,div,aside)[data-ros=decision] { border-radius: var(--ros-radius-md); background: var(--ros-accent-bg); padding: var(--ros-space-4) var(--ros-space-5); margin: var(--ros-space-5) 0; }
