:is(blockquote,section,div,aside)[data-ros=warning] { border-radius: var(--ros-radius-md); background: var(--ros-warning-bg); padding: var(--ros-space-4) var(--ros-space-5); }
[data-ros=hint], [data-ros=solution] { border-radius: var(--ros-radius-md); background: var(--ros-surface-subtle); padding: var(--ros-space-3) var(--ros-space-4); }
/* Authored callouts already have a title/body shell; avoid legacy double padding. */
:is(aside,div,section,details).ros-callout { padding: 0; background: var(--ros-callout-bg); }
details { margin: var(--ros-space-4) 0; }
summary { cursor: pointer; font: 700 15px/1.5 var(--ros-font-ui); padding: var(--ros-space-1) 0; }
details[open] > summary { margin-bottom: var(--ros-space-2); }
[data-ros=legacy] { color: var(--ros-text-muted); font-size: 14px; margin-top: var(--ros-space-7); }

/* Controls: one height, one radius. Variant signals the stakes before the label does. */
