button {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  cursor: pointer; min-height: var(--ros-control-height); padding: 0 18px; margin: var(--ros-space-1);
  border: 1.5px solid var(--ros-border-strong); border-radius: var(--ros-radius-md);
