input[type=range] { display: block; width: min(100%,28rem); accent-color: var(--ros-accent); }
input[type=number], input[type=text], input:not([type]), select { min-height: var(--ros-control-height); border: 1.5px solid var(--ros-border-strong); border-radius: var(--ros-radius-md); padding: 0 var(--ros-space-3); }
textarea { display: block; width: 100%; min-height: 6rem; border: 1.5px solid var(--ros-border-strong); border-radius: var(--ros-radius-md); padding: var(--ros-space-3); resize: vertical; font-family: var(--ros-font-body); font-size: 17px; }
:is(input, select, textarea):hover:not(:disabled) { border-color: var(--ros-text-muted); }
:is(input, select, textarea):focus-visible { border-color: var(--ros-accent); }
:focus-visible { outline: 3px solid var(--ros-focus); outline-offset: 2px; }
[hidden] { display: none !important; }
[data-ros], [id] { scroll-margin-top: var(--ros-space-5); }

/* Save feedback: one quiet line, never a banner. */
.ros-status { color: var(--ros-text-muted); font-size: 13px; line-height: 1.5; }
.ros-session-header .ros-status { margin: var(--ros-space-3) 0 0; }
output[data-ros-feedback] { display: block; margin-top: var(--ros-space-3); font-size: 16px; }

/* Questions */
.ros-question { padding: 0; background: var(--ros-surface); overflow: hidden; }
.ros-question-disclosure { margin: 0; }
.ros-question-summary { list-style: none; display: flex; align-items: center; flex-wrap: wrap; gap: var(--ros-space-3); min-height: 56px; padding: 12px 24px; transition: background-color var(--ros-ease); }
.ros-question-summary::-webkit-details-marker { display: none; }
