.ros-question-body, .ros-question:not(:has(.ros-question-disclosure)) { padding: var(--ros-space-5); }
.ros-question-prompt { font: 400 20px/1.55 var(--ros-font-body); margin: 0 0 var(--ros-space-5); }
.ros-options { border: 0; padding: 0; margin: 0; }
.ros-options legend { font: 14px/1.5 var(--ros-font-ui); color: var(--ros-text-muted); margin-bottom: var(--ros-space-2); }
.ros-options > label:not(.ros-option) { font-weight: 600; }
.ros-option { position: relative; display: flex; align-items: center; gap: 14px; margin: 10px 0; padding: 12px 16px; border: 1.5px solid var(--ros-border); border-radius: var(--ros-radius-md); background: var(--ros-surface); cursor: pointer; min-height: 56px; font-size: 16px; line-height: 1.5; transition: background-color var(--ros-ease), border-color var(--ros-ease); }
/* The letter key is the visible control; the native input stays focusable and labelled. */
.ros-option input { position: absolute; z-index: 1; left: 16px; top: 50%; width: 30px; height: 30px; margin: -15px 0 0; opacity: 0; cursor: inherit; }
.ros-option-letter { flex: 0 0 30px; display: grid; place-items: center; height: 30px; border: 1px solid var(--ros-border); border-radius: 8px; font: 700 14px/1 var(--ros-font-ui); color: var(--ros-text-muted); background: var(--ros-surface-subtle); transition: background-color var(--ros-ease), color var(--ros-ease); }
.ros-option-text { flex: 1; min-width: 0; }
.ros-option:hover:not(:has(:disabled)) { border-color: var(--ros-border-strong); background: var(--ros-surface-subtle); }
.ros-option:has(input:focus-visible) { outline: 3px solid var(--ros-focus); outline-offset: 2px; }
.ros-option:has(:checked) { border-color: var(--ros-accent); background: var(--ros-accent-bg); }
.ros-option:has(:checked) .ros-option-letter { color: var(--ros-on-accent); border-color: var(--ros-accent); background: var(--ros-accent); }
.ros-option[data-feedback=matches] { border-color: var(--ros-success); background: var(--ros-success-bg); }
.ros-option[data-feedback=matches] .ros-option-letter { color: var(--ros-surface); border-color: var(--ros-success); background: var(--ros-success); }
.ros-option[data-feedback=retry] { border-color: var(--ros-danger); background: var(--ros-danger-bg); }
.ros-option[data-feedback=retry] .ros-option-letter { color: var(--ros-surface); border-color: var(--ros-danger); background: var(--ros-danger); }
.ros-option:has(:disabled) { opacity: .6; cursor: default; }
.ros-question-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--ros-space-2); margin-top: var(--ros-space-5); padding-top: var(--ros-space-4); border-top: 1px solid var(--ros-border); }
.ros-question-actions button { margin: 0; }
/* The escape action sits apart from the primary one, so the two are never mis-tapped. */
.ros-question-actions .ros-reset { margin-left: auto; }
.ros-feedback { display: flex; align-items: flex-start; gap: 12px; font: 15px/1.6 var(--ros-font-ui); padding: 14px 16px; margin: var(--ros-space-4) 0; border-radius: var(--ros-radius-md); background: var(--ros-surface-subtle); color: var(--ros-text); }
.ros-feedback::before { content: 'i' / ''; flex: none; display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; background: var(--ros-accent); color: var(--ros-on-accent); font: 700 13px/1 var(--ros-font-ui); }
.ros-feedback[data-state=matches] { background: var(--ros-success-bg); }
.ros-feedback[data-state=matches]::before { content: '✓' / ''; background: var(--ros-success); color: var(--ros-surface); }
.ros-feedback[data-state=retry] { background: var(--ros-danger-bg); }
.ros-feedback[data-state=retry]::before { content: '✕' / ''; background: var(--ros-danger); color: var(--ros-surface); }
.ros-feedback { flex-wrap: wrap; }
.ros-feedback > :not(.ros-verdict-label) { flex: 1 1 100%; padding-left: 36px; }
.ros-verdict-label { font-weight: 700; align-self: center; }
.ros-feedback[data-state=partial] { background: var(--ros-warning-bg); }
.ros-feedback[data-state=partial]::before { content: '~' / ''; background: var(--ros-warning); color: var(--ros-surface); }
/* The explanation appears with the verdict, directly under the answer it explains. */
.ros-explanation { border-left: 3px solid var(--ros-accent); }
.ros-explanation-title { margin: 0 0 4px; font: 700 12px/1.5 var(--ros-font-ui); letter-spacing: .09em; text-transform: uppercase; color: var(--ros-accent); }
.ros-explanation > p:last-child { margin-bottom: 0; white-space: pre-line; }
.ros-form-note { margin: var(--ros-space-2) 0 0; font: 14px/1.5 var(--ros-font-ui); color: var(--ros-danger); }
.ros-question-heading { display: flex; align-items: center; flex-wrap: wrap; gap: var(--ros-space-3); margin-bottom: var(--ros-space-3); }
.ros-question-heading .ros-question-number { margin: 0; }
.ros-question-state[data-state=matches] { color: var(--ros-success); font-weight: 600; }
.ros-question-state[data-state=retry] { color: var(--ros-danger); font-weight: 600; }
.ros-question-state[data-state=partial] { color: var(--ros-warning); font-weight: 600; }
.ros-question-state[data-state=checking], .ros-submit[aria-busy=true] { animation: ros-checking 1.4s ease-in-out infinite; }
.ros-submit[aria-busy=true]:disabled { background: var(--ros-accent-bg); border-color: var(--ros-accent); color: var(--ros-accent); }
@keyframes ros-checking { 50% { opacity: .55; } }
/* Content written while the page is open arrives in place, briefly marked. */
[data-ros-arrived] { animation: ros-arrived 2.4s ease-out; }
@keyframes ros-arrived { from { box-shadow: 0 0 0 4px var(--ros-accent-bg); background-color: var(--ros-accent-bg); } }
.ros-arrival { position: fixed; z-index: 20; left: 50%; bottom: var(--ros-space-5); transform: translateX(-50%); margin: 0; border-radius: 999px; background: var(--ros-accent); border-color: var(--ros-accent); color: var(--ros-on-accent); box-shadow: var(--ros-shadow-sm); }
.ros-arrival:hover:not(:disabled) { background: var(--ros-accent-hover); border-color: var(--ros-accent-hover); }
.ros-hint, .ros-explanation { font-size: 16px; line-height: 1.65; margin: 8px 0 12px; padding: 12px 16px; background: var(--ros-surface-subtle); border-radius: var(--ros-radius-md); }
.ros-reveal { font-size: 14px; margin: 4px 8px 4px 0; }
.ros-confidence { display: flex; flex-wrap: wrap; align-items: center; gap: var(--ros-space-2) var(--ros-space-4); font: 14px/1.5 var(--ros-font-ui); color: var(--ros-text-muted); margin: var(--ros-space-4) 0 0; }
.ros-confidence-scale { display: inline-flex; align-items: center; gap: 4px; padding: 3px; border: 1px solid var(--ros-border); border-radius: 12px; background: var(--ros-surface-subtle); }
.ros-confidence-scale > span { padding: 0 8px; font-size: 13px; }
.ros-confidence-scale button { min-width: 44px; padding: 0; margin: 0; border-color: transparent; border-radius: 9px; background: transparent; color: var(--ros-text-muted); }
.ros-confidence-scale button:hover { background: var(--ros-surface); border-color: transparent; }
.ros-confidence-scale button[aria-pressed=true] { background: var(--ros-accent); border-color: var(--ros-accent); color: var(--ros-on-accent); }
.ros-progress { display: grid; grid-template-columns: 1fr auto; gap: 8px 16px; margin: 0 0 var(--ros-space-5); font: 13px/1.5 var(--ros-font-ui); color: var(--ros-text-muted); }
.ros-progress-label { margin: 0; font: inherit; }
.ros-progress .ros-status { grid-column: 2; grid-row: 1; margin: 0; text-align: right; }
.ros-progress-bar { grid-column: 1 / -1; height: 6px; background: var(--ros-surface-strong); border-radius: 3px; overflow: hidden; }
.ros-progress-bar span { display: block; height: 100%; background: var(--ros-accent); border-radius: 3px; transition: width .2s ease; }
.ros-open-question { margin: var(--ros-space-6) 0; padding: var(--ros-space-5); border: 1px solid var(--ros-border); border-radius: var(--ros-radius-lg); background: var(--ros-surface-subtle); }
.ros-open-question > label { font-weight: 600; margin-top: 0; }
.ros-open-question [role=status] { font: 14px/1.5 var(--ros-font-ui); color: var(--ros-text-muted); }
@media (max-width: 500px) {
  .ros-question-summary, .ros-question-body { padding: var(--ros-space-4); }
  .ros-question-state { margin-left: 0; flex-basis: 100%; }
  .ros-option { gap: 10px; padding: 12px; }
  .ros-option-letter { flex-basis: 26px; height: 26px; }
  .ros-option input { left: 12px; width: 26px; height: 26px; margin-top: -13px; }
  .ros-open-question { padding: var(--ros-space-4); }
  .ros-question-actions .ros-reset { margin-left: 0; }
  .ros-progress { grid-template-columns: 1fr; }
  .ros-progress .ros-status { grid-column: 1; grid-row: auto; text-align: left; }
}

/* Code */
code, pre { font-family: var(--ros-font-mono); font-size: 14px; }
code { background: var(--ros-surface-subtle); padding: .1em .35em; border-radius: var(--ros-radius-sm); }
pre { overflow: auto; white-space: pre; overflow-wrap: normal; padding: var(--ros-space-4); background: var(--ros-surface-subtle); border-radius: var(--ros-radius-md); line-height: 1.65; }
pre code { padding: 0; background: none; }
.ros-code-block { margin: var(--ros-space-5) 0; border-radius: var(--ros-radius-md); background: var(--ros-surface-subtle); overflow: hidden; }
.ros-code-toolbar { display: flex; align-items: center; flex-wrap: wrap; gap: var(--ros-space-2); padding: 2px 4px 2px 16px; border-bottom: 1px solid var(--ros-border); font: 700 12px/1.5 var(--ros-font-ui); letter-spacing: .05em; text-transform: uppercase; color: var(--ros-text-muted); }
.ros-code-toolbar > span:first-child { margin-right: auto; }
.ros-code-toolbar [role=status] { text-transform: none; letter-spacing: 0; font-weight: 600; color: var(--ros-success); }
.ros-code-toolbar button { font-size: 13px; min-height: 36px; padding: 0 12px; margin: 0; border-color: transparent; background: transparent; color: var(--ros-accent); text-transform: none; letter-spacing: 0; }
.ros-code-toolbar button:hover:not(:disabled) { background: var(--ros-accent-bg); border-color: transparent; }
.ros-code-block pre { margin: 0; border-radius: 0; background: transparent; }
.ros-code-block textarea { font: 14px/1.65 var(--ros-font-mono); border-radius: 0; border-width: 1px 0 0; }

/* Tables */
table { display: block; width: 100%; overflow-x: auto; border-collapse: collapse; font-size: 16px; margin: var(--ros-space-5) 0; }
td, th { text-align: left; padding: var(--ros-space-3) var(--ros-space-4); border-bottom: 1px solid var(--ros-border); }
th { font: 700 14px/1.5 var(--ros-font-ui); background: var(--ros-surface-subtle); }
.ros-table-wrap { overflow-x: auto; margin: var(--ros-space-5) 0; }
.ros-table-wrap table { display: table; margin: 0; overflow: visible; min-width: 100%; width: max-content; border-top: 2px solid var(--ros-border-strong); border-bottom: 2px solid var(--ros-border-strong); }
.ros-table-wrap th { border-bottom: 2px solid var(--ros-border-strong); }
.ros-table-wrap .ros-numeric { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.ros-table-wrap .ros-align-center { text-align: center; }
.ros-table-wrap.ros-compact :is(td,th) { padding: 6px 12px; }

/* Figures and equations */
svg, canvas, img { max-width: 100%; height: auto; }
canvas, svg { display: block; margin: var(--ros-space-4) auto; }
/* KaTeX stretch SVGs are glyphs, not figure canvases. */
.katex svg { display: inline; margin: 0; max-width: none; height: inherit; }
figure { margin: var(--ros-space-5) 0; }
figure img { display: block; margin: auto; border-radius: var(--ros-radius-sm); }
.ros-figure { padding: var(--ros-space-4); border: 1px solid var(--ros-border); border-radius: var(--ros-radius-md); background: var(--ros-surface); }
.ros-figure-panels { display: grid; grid-template-columns: repeat(auto-fit,minmax(min(100%,240px),1fr)); gap: var(--ros-space-4); align-items: start; }
.ros-figure-panels figure { margin: 0; }
.ros-formula { border-block: 1px solid var(--ros-border); margin: var(--ros-space-5) 0; }
.ros-callout-formula .ros-formula { border: 0; margin: var(--ros-space-3) 0; }
figcaption, caption { font: 14px/1.5 var(--ros-font-ui); color: var(--ros-text-muted); text-align: left; padding-top: var(--ros-space-3); }
/* Navigation and workspace: where am I, where can I go, and a questions panel that stays reachable. */
@media (max-width: 1439px) {
  /* Without a side rail the contents bar stays reachable while reading, so "where am I" never costs the learner their place. */
  .ros-toc { position: sticky; top: 0; z-index: 20; }
  .ros-toc > details[open] { max-height: min(70vh, 560px); overflow-y: auto; box-shadow: var(--ros-shadow-sm); }
  .ros-document :is(h1, h2, h3, h4, h5, h6) { scroll-margin-top: 64px; }
}
.ros-sr-only { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.ros-section-progress { margin-inline-start: auto; padding-inline-start: var(--ros-space-2); font-size: 12px; font-weight: 400; color: var(--ros-text-muted); white-space: nowrap; }
.ros-toc a[data-progress="done"] .ros-section-progress { color: var(--ros-success); font-weight: 700; }
.ros-toc a[data-progress="partial"] .ros-section-progress { color: var(--ros-warning); }
.ros-nav-extra { display: grid; gap: var(--ros-space-2); margin: 0; padding: var(--ros-space-3) var(--ros-space-2) var(--ros-space-2); border-top: 1px solid var(--ros-border); font: 14px/1.4 var(--ros-font-ui); }
.ros-nav-steps { display: grid; grid-template-columns: 1fr 1fr; gap: var(--ros-space-2); }
.ros-nav-extra button { min-height: 44px; padding: 0 var(--ros-space-2); font-size: 14px; white-space: nowrap; }
.ros-listen { display: grid; gap: var(--ros-space-2); }
.ros-listen-row { display: grid; grid-template-columns: 1fr auto; gap: var(--ros-space-2); }
.ros-listen-note { margin: 0; font-size: 13px; color: var(--ros-text-muted); overflow-wrap: anywhere; }
.ros-listen-note:empty { display: none; }
.ros-listen-options[hidden] { display: none; }
.ros-listen-options label { display: grid; gap: 2px; margin-top: var(--ros-space-2); font-size: 13px; }
.ros-listen-options select { min-height: 40px; max-width: 100%; }
.ros-speaking { background: var(--ros-accent-bg); box-shadow: -4px 0 0 var(--ros-accent); border-radius: var(--ros-radius-sm); }
@media (forced-colors: active) { .ros-speaking { outline: 2px solid Highlight; } }
.ros-where { margin: 0; padding: var(--ros-space-3); background: var(--ros-surface-strong); border-radius: var(--ros-radius-sm); overflow-wrap: anywhere; color: var(--ros-text); }
.ros-where[hidden], .ros-nav-related[hidden] { display: none; }
.ros-nav-heading { margin: var(--ros-space-3) 0 var(--ros-space-1); font: 700 12px/1.4 var(--ros-font-ui); text-transform: uppercase; letter-spacing: .09em; color: var(--ros-text-muted); }
.ros-nav-related ul { list-style: none; margin: 0; padding: 0; }
.ros-nav-related li { display: grid; gap: 2px; padding: var(--ros-space-2) var(--ros-space-1); }
.ros-nav-kind { font-size: 12px; color: var(--ros-text-muted); }
a.ros-note-link { color: var(--ros-accent); text-decoration: underline dotted; text-underline-offset: 3px; cursor: pointer; }
a.ros-note-link:hover { text-decoration-style: solid; }
.ros-note-link-invalid { color: var(--ros-text-muted); border-bottom: 1px dotted currentColor; }
.ros-note-hint { display: inline-block; margin-inline-start: .5em; padding: 0 .6em; font: 13px/1.6 var(--ros-font-ui); color: var(--ros-text); border: 1px solid var(--ros-border-strong); border-radius: 999px; background: var(--ros-surface-subtle); }
.ros-note-hint[data-state="problem"] { color: var(--ros-warning); background: var(--ros-warning-bg); border-color: currentColor; }
.ros-side-panel { position: fixed; z-index: 40; top: 0; right: 0; bottom: 0; width: min(92vw, 400px); overflow-y: auto; padding: var(--ros-space-5); background: var(--ros-surface); border-left: 1px solid var(--ros-border); box-shadow: var(--ros-shadow-sm); overflow-wrap: anywhere; }
.ros-side-panel[hidden] { display: none; }
.ros-side-panel-head { display: flex; align-items: center; justify-content: space-between; gap: var(--ros-space-3); }
.ros-side-panel-title { margin: 0; font: 700 18px/1.3 var(--ros-font-ui); }
.ros-side-panel .ros-open-question { margin: var(--ros-space-4) 0; padding: var(--ros-space-4); }
.ros-side-panel .ros-question-composer textarea { min-height: 10rem; }   /* a spoken question runs several lines, and Send sits over the bottom right corner */
.ros-side-panel .ros-question-history { margin: var(--ros-space-4) 0 0; }
.ros-side-panel .ros-question-history > h2 { font-size: 16px; margin-top: 0; }
.ros-question-entry { padding: var(--ros-space-3) 0; border-top: 1px solid var(--ros-border); }
.ros-question-entry .ros-question-state { float: right; font: 600 13px/1.5 var(--ros-font-ui); color: var(--ros-text-muted); }
/* Whether anyone is listening, said plainly: text carries the meaning, the edge colour only echoes it. */
.ros-supervision { grid-column: 1 / -1; margin: var(--ros-space-2) 0 0; padding: var(--ros-space-2) var(--ros-space-3); border-left: 4px solid var(--ros-border-strong); border-radius: var(--ros-radius-sm); background: var(--ros-surface-subtle); color: var(--ros-text); font: 14px/1.5 var(--ros-font-ui); }
.ros-supervision[hidden] { display: none; }
.ros-supervision:is([data-status="waiting-for-learner"], [data-status="active"]) { border-left-color: var(--ros-success); }
.ros-supervision:is([data-status="response-awaiting-review"], [data-status="agent-reviewing"]) { border-left-color: var(--ros-accent); }
.ros-supervision:is([data-status="disconnected"], [data-status="paused"]) { border-left-color: var(--ros-warning); background: var(--ros-warning-bg); }
.ros-supervision[data-status="failed-recoverable"] { border-left-color: var(--ros-danger); background: var(--ros-danger-bg); }
.ros-explain { margin: var(--ros-space-4) 0; }
.ros-explain-title { margin: 0 0 var(--ros-space-2); font: 700 14px/1.4 var(--ros-font-ui); }
.ros-explain-modes { display: flex; flex-wrap: wrap; gap: var(--ros-space-2); }
.ros-explain-mode { min-height: 36px; padding: 0 var(--ros-space-3); border-radius: 999px; font-size: 13px; }
.ros-explain-note { margin: var(--ros-space-2) 0 0; font: 13px/1.5 var(--ros-font-ui); color: var(--ros-text-muted); }
.ros-explain-note:empty { display: none; }
.ros-waiting-title { margin: var(--ros-space-4) 0 var(--ros-space-1); font: 700 14px/1.4 var(--ros-font-ui); }
.ros-waiting ul { list-style: none; margin: 0; padding: 0; font: 14px/1.5 var(--ros-font-ui); color: var(--ros-text-muted); }
.ros-waiting li { padding: var(--ros-space-1) 0; }
button.ros-return { min-height: 32px; padding: 0 var(--ros-space-2); border-color: transparent; background: transparent; color: var(--ros-accent); font-size: 14px; text-align: left; }
.ros-panel-toggle { position: fixed; z-index: 39; right: 16px; bottom: 16px; display: inline-flex; align-items: center; gap: var(--ros-space-2); min-height: 44px; padding: 0 var(--ros-space-4); border-radius: 999px; box-shadow: var(--ros-shadow-sm); }
.ros-side-panel:not([hidden]) ~ .ros-panel-toggle { display: none; }
.ros-panel-toggle[data-fresh="true"] { background: var(--ros-accent); color: var(--ros-on-accent); border-color: var(--ros-accent); }
.ros-panel-toggle[data-fresh="true"] .ros-count { background: var(--ros-on-accent); color: var(--ros-accent); }
.ros-count { min-width: 1.6em; padding: 0 .4em; border-radius: 999px; background: var(--ros-accent); color: var(--ros-on-accent); font-size: 12px; font-weight: 700; text-align: center; }
@media (min-width: 1600px) {
  /* Three areas: navigation left, the lesson in the middle, questions right. */
  .ros-side-panel { top: 24px; right: 24px; bottom: 24px; width: 320px; border: 1px solid var(--ros-border); border-radius: var(--ros-radius-lg); }
  .ros-panel-toggle, .ros-panel-close { display: none; }
  .ros-document { margin-inline: auto 368px; }
  .ros-document:has(.ros-toc) { margin-left: calc((100vw - 1036px) / 2); margin-right: auto; }
  .ros-toc { margin: 0 72px 0 -292px; } /* the rail sits 24px outside the lesson's padded box; net zero effect on text flow */
}
/* A figure says what kind of evidence it is; a placement problem is shown in the lesson, never hidden. */
.ros-visual-class { display: inline-block; margin-inline-start: var(--ros-space-2); padding: 0 .55em; border: 1px solid var(--ros-border); border-radius: 999px; font-size: 12px; white-space: normal; }
aside.ros-diagnostic { display: block; margin: var(--ros-space-4) 0; padding: var(--ros-space-3) var(--ros-space-4); border: 1px dashed currentColor; border-radius: var(--ros-radius-sm); overflow-wrap: anywhere; }
div[data-ros=equation], .katex-display { overflow-x: auto; overflow-y: hidden; padding: var(--ros-space-3) 0; }
span[data-ros=equation] { padding: 0; }
[data-math-status=unsupported] { white-space: pre-wrap; border: 1px solid var(--ros-warning); border-radius: var(--ros-radius-sm); padding: var(--ros-space-3); }

/* Open questions and conversation */
.ros-question-composer { position: relative; }
.ros-question-composer textarea { min-height: 8rem; padding-bottom: 4rem; }
.ros-question-send { position: absolute; right: var(--ros-space-3); bottom: var(--ros-space-3); margin: 0; }
/* Asking aloud: only present where the host can record. The transcript fills the box above; Send stays the learner's act. */
.ros-voice-row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--ros-space-3); margin-top: var(--ros-space-3); }
.ros-voice-row[hidden] { display: none; }
.ros-voice-talk { touch-action: none; user-select: none; cursor: pointer; }
.ros-voice-talk[data-voice=starting], .ros-voice-talk[data-voice=recording] { border-color: var(--ros-warning); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ros-warning) 35%, transparent); }
.ros-voice-talk[data-voice=recording]::before { content: ""; display: inline-block; width: .6em; height: .6em; margin-right: .5em; border-radius: 50%; background: var(--ros-warning); animation: ros-voice-pulse 1s ease-in-out infinite; }
.ros-voice-talk:disabled { cursor: progress; }
.ros-voice-line { margin: 0; font: 14px/1.5 var(--ros-font-ui); color: var(--ros-text-muted); flex: 1 1 14rem; }
.ros-voice-line.ros-voice-problem { color: var(--ros-warning); }
@keyframes ros-voice-pulse { 50% { opacity: .35; } }
@media (prefers-reduced-motion: reduce) { .ros-voice-talk[data-voice=recording]::before { animation: none; } }
form[data-ros=open-question]:not(.ros-open-question) { border-top: 1px solid var(--ros-border); padding-top: var(--ros-space-5); margin-top: var(--ros-space-7); }
.ros-question-entry { border-top: 1px solid var(--ros-border); padding: var(--ros-space-4) 0; }
.ros-question-entry p { white-space: pre-wrap; overflow-wrap: anywhere; }
.ros-question-entry h3 { font-size: 16px; margin: var(--ros-space-2) 0; color: var(--ros-accent); }
.ros-question-entry small { font-family: var(--ros-font-ui); color: var(--ros-text-muted); }
.ros-question-answer { border-radius: var(--ros-radius-md); background: var(--ros-surface-subtle); padding: var(--ros-space-1) var(--ros-space-4); }
.ros-heading-anchor { display: block; height: 0; }
.ros-document > :is(figure, .ros-table-wrap).ros-wide {
  width: min(var(--ros-wide-width), calc(100vw - 64px)); max-width: none;
  margin-left: calc((100% - min(var(--ros-wide-width), calc(100vw - 64px))) / 2);
}
@media (max-width: 1000px) { main { margin: 0 auto; padding: var(--ros-space-6); } .ros-document { border-radius: 0; } }
@media (max-width: 500px) {
  :root { font-size: 17px; }
  main { padding: var(--ros-space-4); }
  h1 { font-size: 30px; }
  h2 { font-size: 22px; }
  fieldset:not(.ros-options), [data-question-id]:not(.ros-question), [data-ros=widget] { padding: var(--ros-space-3); }
}
@media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; scroll-behavior: auto !important; } }
@media (forced-colors: active) { .ros-option input { opacity: 1; position: static; width: auto; height: auto; } }
@media print {
  :root, :root:not([data-theme=light]), :root[data-theme=dark] {
    color-scheme: light; --ros-bg: white; --ros-text: black; --ros-text-muted: #444;
    --ros-surface: white; --ros-surface-subtle: #f4f4f4; --ros-border: #bbb;
    --ros-practice-bg: white; --ros-warning-bg: white; --ros-accent-bg: white; --ros-success-bg: white; --ros-accent: #1f5f8b;
  }
  button, form, .ros-status, .ros-progress { display: none; }
  .ros-toc, .ros-side-panel, .ros-panel-toggle, .ros-note-hint { display: none; }
  .ros-document, .ros-document:has(.ros-toc) { margin-left: 0; margin-right: 0; }
  main { max-width: none; padding: 0; margin: 0; box-shadow: none; }
  h1, h2, h3 { break-after: avoid; }
  figure { break-inside: avoid; }
  pre { white-space: pre-wrap; overflow-wrap: anywhere; }
}

/* Research OS blackboard (board.js). The board is always chalk on dark slate, whatever the page theme; only the controls under it follow the page. */
/* A hand is the writing font; a paired hand uses one font for titles (the large and huge sizes) and the other for everything else. */
.ros-board{margin:1.5rem 0;--board-font:"Kalam","Atkinson Hyperlegible Next",system-ui,sans-serif;--board-title:var(--board-font);--title-weight:700}
.ros-board[data-hand="patrick"]{--board-font:"Patrick Hand","Atkinson Hyperlegible Next",system-ui,sans-serif;--title-weight:400}
.ros-board[data-hand="caveat"]{--board-font:"Caveat","Kalam",system-ui,sans-serif;--title-weight:400}
.ros-board[data-hand="kalam-patrick"]{--board-title:"Kalam","Atkinson Hyperlegible Next",system-ui,sans-serif;--board-font:"Patrick Hand","Atkinson Hyperlegible Next",system-ui,sans-serif}
.ros-board[data-hand="patrick-kalam"]{--board-title:"Patrick Hand","Atkinson Hyperlegible Next",system-ui,sans-serif;--title-weight:400;--board-font:"Kalam","Atkinson Hyperlegible Next",system-ui,sans-serif}
.ros-board-write[data-size="huge"],.ros-board-write[data-size="large"]{font-family:var(--board-title);font-weight:var(--title-weight)}
.ros-board-frame{background:#4a3b2c;padding:clamp(6px,1.2vw,14px);border-radius:6px;box-shadow:0 2px 0 #2f2418,0 10px 24px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.12)}
.ros-board-surface{position:relative;aspect-ratio:16/9;overflow:hidden;border-radius:3px;background:
  radial-gradient(130% 100% at 25% 15%,rgba(255,255,255,.07),transparent 55%),
  radial-gradient(120% 90% at 85% 95%,rgba(0,0,0,.4),transparent 60%),
  repeating-linear-gradient(100deg,rgba(255,255,255,.012) 0 6px,transparent 6px 14px),#1c2421;box-shadow:inset 0 0 40px rgba(0,0,0,.55);color:#f4f0e6}
/* The page gives every svg a block display, auto margins and a max width (theme.css); the ink must sit exactly on the board or drawings drift off the text. */
.ros-board-ink{position:absolute;inset:0;width:100%;height:100%;max-width:none;margin:0;display:block}
.ros-board-text{position:absolute;inset:0;pointer-events:none}
/* A text item is placed by board.js in board units: left and top are percentages of the board, its width (when it has one) too, and its font size follows the board's
   width, so text and drawing scale together. 1.25 is the line height board.js lays out with (LINE in board.js and board_script.py). */
.ros-board-item{position:absolute;white-space:pre;line-height:1.25;color:var(--ink,#f4f0e6);font-family:var(--board-font);text-align:left;
  font-size:calc(var(--fs,3.2) * var(--bw,800px) / 100);letter-spacing:.01em;text-shadow:0 0 .6px currentColor,0 0 7px rgba(244,240,230,.16)}
.ros-board-item[data-wrap="1"]{white-space:pre-wrap;overflow-wrap:anywhere}
.ros-board-math{font-family:"KaTeX_Main","Times New Roman",serif;white-space:nowrap}
.ros-board-math .katex{font-size:1.05em;color:inherit}
/* The page's .katex svg { display: inline } would push the radical sign of a square root off its place; KaTeX needs it as a block. */
.ros-board-math .katex svg{display:block}
.ros-board-math small{font-size:.5em}
.ros-board-pen{position:absolute;left:0;top:0;width:0;height:0;pointer-events:none}
.ros-board-pen::after{content:"";position:absolute;left:-1px;top:-4px;width:18px;height:7px;border-radius:2px;background:#f2eee3;transform:rotate(-38deg);transform-origin:left center;box-shadow:0 0 8px rgba(255,255,255,.55)}
.ros-board-pen[hidden],.ros-board-hint[hidden]{display:none}
.ros-board-hint{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--board-font);font-size:calc(4.4 * var(--bw,800px) / 100);color:rgba(244,240,230,.32);pointer-events:none}
.ros-board-bar{display:flex;flex-wrap:wrap;gap:.5rem .9rem;align-items:center;margin-top:.7rem}
.ros-board-bar button{min-height:2.25rem;padding:.3rem .9rem;cursor:pointer}
.ros-board-bar button:disabled{cursor:default;opacity:.55}
.ros-board-bar label{display:inline-flex;gap:.35rem;align-items:center}
.ros-board-state{opacity:.8}
.ros-board-caption{min-height:1.6em;margin:.5rem 0 0;font-style:italic}
.ros-board-transcript{margin-top:.4rem}
.ros-board-transcript li[aria-current="step"]{font-weight:600}
.ros-board-written{opacity:.75}
.ros-board-voice-note{margin:.4rem 0 0;min-height:1.3em;font-size:.9rem;opacity:.85}
.ros-board-voice-note[data-problem="true"]{color:#b45309}

/* Research OS staged session (stages.js). The complete active stage fits the viewport; long supporting content uses pages, never hidden overflow. */
body.ros-staged main.ros-document{max-width:none;margin:0;padding:0;background:transparent;box-shadow:none;border-radius:0}
body.ros-staged main.ros-document > :not(.ros-stages){display:none}
body.ros-staged .ros-side-panel,body.ros-staged .ros-panel-toggle,body.ros-staged .ros-arrival{display:none}
.ros-stages{display:flex;flex-direction:column;height:100vh;height:100dvh;min-height:0;box-sizing:border-box;max-width:64rem;margin:0 auto;padding:12px;gap:12px}
.ros-stages nav,.ros-stages ol,.ros-stages ul{margin:0}
